def hora_now():
    return now_app().strftime("%H:%M:%S")


def money(v):
    try:
        return "S/ {:,.2f}".format(float(v or 0))
    except Exception:
        return "S/ 0.00"


def clean_text(v):
    if v is None or (hasattr(pd, "isna") and pd.isna(v)):
        return ""
    return str(v).strip()


def extract_dni(v):
    """Extrae un DNI peruano de 8 digitos desde texto manual, QR o codigo de barras.
    Prioriza numeros asociados a DNI/documento y evita devolver cadenas largas completas.
    """
    raw = str(v or "").strip()
    if not raw:
        return ""
    digits_only = re.sub(r"\D", "", raw)
    if len(digits_only) == 8:
        return digits_only
    if 1 <= len(digits_only) < 8:
        return digits_only.zfill(8)

    txt = raw.upper()
    m = re.search(r"(?:DNI|DOC(?:UMENTO)?|NRO|NUM(?:ERO)?)\D{0,12}(\d{8})(?!\d)", txt)
    if m:
        return m.group(1)
    m = re.search(r"(?<!\d)(\d{8})(?!\d)", txt)
    if m:
        return m.group(1)
    if len(digits_only) > 8:
        return digits_only[-8:]
    return ""

def clean_dni(v):
    return extract_dni(v)


def clean_codigo(v):
    """Normaliza el código interno del trabajador sin destruir ceros a la izquierda si vienen como texto."""
    if v is None or (hasattr(pd, "isna") and pd.isna(v)):
        return ""
    if isinstance(v, bool):
        return str(v).upper()
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float) and v.is_integer():
        return str(int(v))
    raw = str(v).strip().upper()
    # Excel suele convertir códigos numéricos a texto tipo 12345.0.
    if re.fullmatch(r"\d+\.0+", raw):
        raw = raw.split(".", 1)[0]
    return re.sub(r"\s+", "", raw)[:80]


def resolver_trabajador(identificador):
    """Busca un trabajador activo por DNI o por CODIGO.

    Prioridad:
    1) Si se digitó exactamente 8 dígitos, primero intenta DNI (compatibilidad histórica).
    2) Intenta CODIGO exacto.
    3) Si el QR contiene un DNI de 8 dígitos dentro de un texto mayor, intenta ese DNI.
    Devuelve (trabajador, tipo, valor_normalizado, mensaje_error).
    """
    raw = clean_text(identificador)
    if not raw:
        return None, "", "", "Ingresa DNI o CÓDIGO."

    codigo = clean_codigo(raw)
    raw_digits = re.sub(r"\D", "", raw)

    if re.fullmatch(r"\d{8}", codigo or ""):
        t = q_one("SELECT * FROM trabajadores WHERE dni=? AND activo=1", (codigo,))
        if t:
            return t, "DNI", codigo, ""

    if codigo:
        # Búsqueda exacta por código. Para códigos puramente numéricos también
        # tolera ceros a la izquierda (ej.: 002694 == 2694), sin afectar
        # códigos alfanuméricos. Si la normalización produce más de una
        # coincidencia se bloquea para no traer al trabajador equivocado.
        if re.fullmatch(r"\d+", codigo):
            coinciden = q_all(
                """
                SELECT * FROM trabajadores
                WHERE activo=1 AND COALESCE(codigo,'')<>''
                  AND (codigo=? OR LTRIM(codigo,'0')=LTRIM(?,'0'))
                ORDER BY id LIMIT 3
                """,
                (codigo, codigo),
            )
        else:
            coinciden = q_all(
                "SELECT * FROM trabajadores WHERE UPPER(TRIM(codigo))=? AND activo=1 ORDER BY id LIMIT 3",
                (codigo,),
            )
        # Evita contar dos veces el mismo registro cuando cumple ambas condiciones.
        unicos = []
        vistos = set()
        for r in coinciden:
            rid = r["id"]
            if rid not in vistos:
                vistos.add(rid)
                unicos.append(r)
        if len(unicos) == 1:
            return unicos[0], "CODIGO", codigo, ""
        if len(unicos) > 1:
            return None, "CODIGO", codigo, f"Código duplicado/ambiguo en la base: {codigo}. Corrige el maestro de trabajadores."

    # No usar el relleno con ceros de clean_dni para códigos cortos.
    dni = ""
    if len(raw_digits) >= 8:
        dni = extract_dni(raw)
    if len(dni) == 8:
        t = q_one("SELECT * FROM trabajadores WHERE dni=? AND activo=1", (dni,))
        if t:
            return t, "DNI", dni, ""

    return None, "", codigo or raw, f"DNI/CÓDIGO no encontrado o trabajador inactivo: {codigo or raw}"


def cfg_get(clave, default=""):
    r = q_one("SELECT valor FROM configuracion WHERE clave=?", (clave,))
    return r["valor"] if r else default

def cfg_set(clave, valor):
    existe = q_one("SELECT clave FROM configuracion WHERE clave=?", (clave,))
    if existe:
        q_exec("UPDATE configuracion SET valor=? WHERE clave=?", (str(valor), clave))
    else:
        q_exec("INSERT INTO configuracion(clave,valor) VALUES(?,?)", (clave, str(valor)))

def registro_bloqueado():
    if cfg_get("bloqueo_activo", "0") != "1":
        return False, ""
    ahora = now_app().strftime("%H:%M")
    inicio = cfg_get("hora_inicio", "00:00")
    fin = cfg_get("hora_fin", "23:59")
    if inicio <= ahora <= fin:
        return False, ""
    return True, f"Registro bloqueado por horario. Horario permitido: {inicio} a {fin}."

def require_remove_key(clave):
    return str(clave or "").strip() == cfg_get("clave_quitar", "1234")

