TIPOS_ALIMENTACION = ["DESAYUNO", "ALMUERZO", "DIETA", "CENA"]

def normalizar_tipo_alimentacion(v):
    tipo = clean_text(v).upper()
    aliases = {
        "ALMUERZO EN CAMPO": "ALMUERZO",
        "ALMUERZO EN COMEDOR": "ALMUERZO",
        "ALMUERZO": "ALMUERZO",
        "DESAYUNO": "DESAYUNO",
        "DIETA": "DIETA",
        "CENA": "CENA",
    }
    return aliases.get(tipo, "ALMUERZO")

def proveedores_comedor_activos():
    return q_all("SELECT * FROM proveedores_comedor WHERE activo=1 ORDER BY nombre")

def proveedor_por_nombre(nombre):
    return q_one("SELECT * FROM proveedores_comedor WHERE UPPER(TRIM(nombre))=UPPER(TRIM(?)) AND activo=1", (clean_text(nombre),))

def precio_por_proveedor_tipo(nombre, tipo):
    prov = proveedor_por_nombre(nombre)
    if not prov:
        return None
    tipo = normalizar_tipo_alimentacion(tipo)
    campo = {
        "DESAYUNO": "precio_desayuno",
        "ALMUERZO": "precio_almuerzo",
        "DIETA": "precio_dieta",
        "CENA": "precio_cena",
    }[tipo]
    return float(prov[campo] or 0)


def normalize_columns(cols):
    out = []
    for c in cols:
        x = str(c).strip().upper()
        for a, b in [("Á","A"),("É","E"),("Í","I"),("Ó","O"),("Ú","U"),("Ñ","N")]:
            x = x.replace(a, b)
        x = re.sub(r"[^A-Z0-9]+", "_", x).strip("_")
        out.append(x)
    return out

def col_value(row, *names):
    """Obtiene valores aunque el Excel venga con nombres de columnas distintos.
    Se aceptan reportes de consumo, plantillas y bases exportadas desde otros sistemas.
    """
    aliases = {
        "DNI": [
            "DNI", "DOCUMENTO", "DOCUMENTO_IDENTIDAD", "NUMERO_DOCUMENTO",
            "NUMERO_DE_DOCUMENTO", "NRO_DOCUMENTO", "NRO_DNI", "DOC", "CEDULA",
            "IDENTIFICACION", "NUM_DOC", "DOCUMENTO_NACIONAL_DE_IDENTIDAD"
        ],
        "NOMBRE": [
            "NOMBRE", "NOMBRES", "APELLIDOS_Y_NOMBRES", "APELLIDOS_NOMBRES",
            "APELLIDOS_Y_NOMBRE", "NOMBRE_COMPLETO", "TRABAJADOR", "COLABORADOR",
            "APELLIDOS", "PERSONAL", "EMPLEADO", "NOMBRE_ACTIVIDAD", "NOMBRE__ACTIVIDAD_",
            "NOMBRE_Y_APELLIDOS", "APELLIDOS_Y_NOMBRES_COMPLETOS"
        ],
        "EMPRESA": ["EMPRESA", "RAZON_SOCIAL", "COMPANIA", "CIA", "ORGANIZACION"],
        "PLANILLA": ["PLANILLA", "TIPO_PLANILLA", "TIPO_DE_PLANILLA", "REGIMEN", "NOMINA"],
        "CODIGO": ["CODIGO", "COD", "COD_TRABAJADOR", "CODIGO_TRABAJADOR", "COD_PERSONAL", "CODIGO_PERSONAL", "COD_EMPLEADO", "CODIGO_EMPLEADO", "ID_TRABAJADOR", "ID_PERSONAL"],
        "CARGO": ["CARGO", "PUESTO", "OCUPACION", "FUNCION", "LABOR", "ACTIVIDAD"],
        "AREA": ["AREA", "AREA_TRABAJO", "SEDE", "FUNDO", "UNIDAD", "DEPARTAMENTO", "CENTRO_COSTO"],
    }
    for name in names:
        for key in aliases.get(name, [name]):
            try:
                val = row.get(key, "")
            except Exception:
                val = ""
            if clean_text(val):
                return val
    return ""


def _normalizar_fila_trabajador(row):
    dni = clean_dni(col_value(row, "DNI"))
    nombre = clean_text(col_value(row, "NOMBRE")).upper()
    if len(dni) != 8 or not nombre:
        return None
    return {
        "empresa": (clean_text(col_value(row, "EMPRESA")) or "APB SAC").upper(),
        "planilla": clean_text(col_value(row, "PLANILLA")).upper(),
        "codigo": clean_codigo(col_value(row, "CODIGO")),
        "dni": dni,
        "nombre": nombre,
        "cargo": clean_text(col_value(row, "CARGO")).upper(),
        "area": clean_text(col_value(row, "AREA")).upper(),
    }


def _buscar_cabecera_excel(rows_preview):
    """Detecta la fila de cabecera aunque el Excel tenga títulos arriba."""
    mejor_idx = 0
    mejor_score = -1
    for idx, row in enumerate(rows_preview[:25]):
        cols = normalize_columns(row)
        joined = "|".join(cols)
        score = 0
        if any(x in joined for x in ["DNI", "DOCUMENTO", "NRO_DNI", "NUMERO_DOCUMENTO"]):
            score += 3
        if any(x in joined for x in ["NOMBRE", "TRABAJADOR", "COLABORADOR", "APELLIDOS"]):
            score += 3
        if "EMPRESA" in joined:
            score += 1
        if "CODIGO" in joined or "COD_TRABAJADOR" in joined or "COD_PERSONAL" in joined:
            score += 1
        if "AREA" in joined or "FUNDO" in joined:
            score += 1
        if score > mejor_score:
            mejor_idx = idx
            mejor_score = score
    return mejor_idx if mejor_score >= 3 else 0


def leer_trabajadores_excel_stream(file_storage):
    """Lee TODO el Excel de trabajadores.
    - Lee todas las hojas.
    - Detecta cabeceras aunque no estén en la primera fila.
    - Acepta columnas de reportes: DNI, CODIGO, TRABAJADOR, EMPRESA, AREA.
    - CODIGO es opcional y sirve como identificador alternativo de lectura.
    - No exige CARGO ni AREA para no perder trabajadores válidos.
    Devuelve: registros(dict por DNI), total_filas, omitidos.
    """
    filename = (file_storage.filename or "").lower()
    registros = {}
    omitidos = 0
    total = 0
    file_storage.stream.seek(0)

    if filename.endswith(".xlsx"):
        wb = load_workbook(file_storage.stream, read_only=True, data_only=True)
        try:
            for ws in wb.worksheets:
                all_rows = list(ws.iter_rows(values_only=True))
                if not all_rows:
                    continue
                header_idx = _buscar_cabecera_excel(all_rows[:25])
                cols = normalize_columns(all_rows[header_idx])
                for values in all_rows[header_idx + 1:]:
                    if not values or not any(clean_text(v) for v in values):
                        continue
                    total += 1
                    r = dict(zip(cols, values))
                    item = _normalizar_fila_trabajador(r)
                    if not item:
                        omitidos += 1
                        continue
                    registros[item["dni"]] = item
        finally:
            wb.close()
        return registros, total, omitidos

    # Para .xls u otros casos: intentar con pandas si el ambiente tiene motor disponible.
    file_storage.stream.seek(0)
    try:
        hojas = pd.read_excel(file_storage, dtype=str, sheet_name=None).items()
    except Exception:
        file_storage.stream.seek(0)
        hojas = [("Hoja1", pd.read_excel(file_storage, dtype=str))]

    for _, df in hojas:
        df = df.fillna("")
        if df.empty:
            continue
        df.columns = normalize_columns(df.columns)
        for _, r in df.iterrows():
            total += 1
            item = _normalizar_fila_trabajador(r)
            if not item:
                omitidos += 1
                continue
            registros[item["dni"]] = item
    return registros, total, omitidos


def reemplazar_trabajadores_batch(registros):
    """Reemplaza la tabla trabajadores en una sola transacción SQLite."""
    data = [(r["empresa"], r.get("planilla", ""), r.get("codigo", ""), r["dni"], r["nombre"], r["cargo"], r["area"]) for r in registros]
    if not data:
        return 0
    with get_conn() as conn:
        conn.execute("DELETE FROM trabajadores")
        conn.executemany(
            "INSERT INTO trabajadores(empresa,planilla,codigo,dni,nombre,cargo,area,activo) VALUES(?,?,?,?,?,?,?,1)",
            data,
        )
        conn.commit()
    return len(data)


def validar_fecha_iso(valor, fallback=None):
    valor = clean_text(valor)
    if not valor:
        return fallback or hoy_iso()
    try:
        return datetime.strptime(valor, "%Y-%m-%d").date().isoformat()
    except Exception:
        return fallback or hoy_iso()


def dia_cerrado(fecha_iso=None):
    fecha_iso = validar_fecha_iso(fecha_iso, hoy_iso())
    return q_one("SELECT * FROM cierres WHERE fecha=?", (fecha_iso,))


def estado_dia(fecha_iso=None, auto_abrir_hoy=True):
    """Devuelve ABIERTO, CERRADO o NO_ABIERTO.

    Regla operativa:
    - Un cierre existente siempre manda y deja el día CERRADO.
    - El día de hoy se abre automáticamente si nunca fue gestionado.
    - Una fecha futura o pasada NO queda abierta por defecto: el administrador
      debe abrirla explícitamente desde Cerrar día.
    """
    fecha = validar_fecha_iso(fecha_iso, hoy_iso())
    if dia_cerrado(fecha):
        return "CERRADO"
    row = q_one("SELECT estado FROM dias_operativos WHERE fecha=?", (fecha,))
    if row:
        estado = clean_text(row["estado"]).upper()
        return estado if estado in ("ABIERTO", "CERRADO") else "NO_ABIERTO"
    if auto_abrir_hoy and fecha == hoy_iso():
        q_exec("""
            INSERT OR IGNORE INTO dias_operativos(fecha,estado,abierto_por,abierto_en)
            VALUES(?,?,?,?)
        """, (fecha, "ABIERTO", "SISTEMA", now_app().strftime("%Y-%m-%d %H:%M:%S")))
        return "ABIERTO"
    return "NO_ABIERTO"


def dia_abierto(fecha_iso=None):
    return estado_dia(fecha_iso) == "ABIERTO"


def abrir_dia_operativo(fecha_iso, usuario=None, reabrir=True):
    fecha = validar_fecha_iso(fecha_iso, hoy_iso())
    usuario = clean_text(usuario) or session.get("user", "admin") or "admin"
    if reabrir:
        q_exec("DELETE FROM cierres WHERE fecha=?", (fecha,))
    q_exec("""
        INSERT INTO dias_operativos(fecha,estado,abierto_por,abierto_en,cerrado_por,cerrado_en)
        VALUES(?,?,?,?,?,?)
        ON CONFLICT(fecha) DO UPDATE SET
          estado='ABIERTO', abierto_por=excluded.abierto_por, abierto_en=excluded.abierto_en,
          cerrado_por='', cerrado_en=''
    """, (fecha, "ABIERTO", usuario, now_app().strftime("%Y-%m-%d %H:%M:%S"), "", ""))
    audit_event("ABRIR_DIA", "dias_operativos", fecha, f"Fecha {fecha}")
    return fecha


def marcar_dia_cerrado(fecha_iso, usuario=None):
    fecha = validar_fecha_iso(fecha_iso, hoy_iso())
    usuario = clean_text(usuario) or session.get("user", "admin") or "admin"
    ahora = now_app().strftime("%Y-%m-%d %H:%M:%S")
    q_exec("""
        INSERT INTO dias_operativos(fecha,estado,abierto_por,abierto_en,cerrado_por,cerrado_en)
        VALUES(?,?,?,?,?,?)
        ON CONFLICT(fecha) DO UPDATE SET
          estado='CERRADO', cerrado_por=excluded.cerrado_por, cerrado_en=excluded.cerrado_en
    """, (fecha, "CERRADO", usuario, ahora, usuario, ahora))
    audit_event("CERRAR_DIA", "dias_operativos", fecha, f"Fecha {fecha}")
    return fecha


def info_dia(fecha_iso=None):
    fecha = validar_fecha_iso(fecha_iso, hoy_iso())
    estado = estado_dia(fecha)
    row = q_one("SELECT * FROM dias_operativos WHERE fecha=?", (fecha,))
    return {
        "fecha": fecha,
        "estado": estado,
        "abierto": estado == "ABIERTO",
        "cerrado": estado == "CERRADO",
        "abierto_por": row["abierto_por"] if row else "",
        "abierto_en": row["abierto_en"] if row else "",
        "cerrado_por": row["cerrado_por"] if row else "",
        "cerrado_en": row["cerrado_en"] if row else "",
    }


def login_required(fn):
    @wraps(fn)
    def wrapper(*args, **kwargs):
        if not session.get("user"):
            return redirect(url_for("login"))
        return fn(*args, **kwargs)
    return wrapper


def roles_required(*roles):
    def deco(fn):
        @wraps(fn)
        def wrapper(*args, **kwargs):
            role = session.get("role")
            if role == "admin" or role in roles:
                return fn(*args, **kwargs)
            flash("No tienes permiso para esta opción.", "error")
            return redirect(url_for("dashboard"))
        return wrapper
    return deco


def asegurar_rol_usuario(role):
    return "admin" if role == "admin" else "comedor"


def send_report_email(to_email, subject, body, attachment_path):
    host = os.getenv("SMTP_HOST", "").strip()
    user = os.getenv("SMTP_USER", "").strip()
    password = os.getenv("SMTP_PASSWORD", "").strip()
    port = int(os.getenv("SMTP_PORT", "587"))
    sender = os.getenv("SMTP_FROM", user or "no-reply@apb.local")

    if not host or not user or not password or not to_email:
        note = os.path.join(REPORT_DIR, f"correo_no_enviado_{now_app().strftime('%Y%m%d_%H%M%S')}.txt")
        with open(note, "w", encoding="utf-8") as f:
            f.write("SMTP no configurado. El Excel fue generado correctamente.\n\n")
            f.write(f"Para: {to_email}\nAsunto: {subject}\nAdjunto: {attachment_path}\n\n{body}")
        return "NO ENVIADO - SMTP NO CONFIGURADO"

    msg = EmailMessage()
    msg["From"] = sender
    msg["To"] = to_email
    msg["Subject"] = subject
    msg.set_content(body)

    with open(attachment_path, "rb") as f:
        msg.add_attachment(
            f.read(),
            maintype="application",
            subtype="vnd.openxmlformats-officedocument.spreadsheetml.sheet",
            filename=os.path.basename(attachment_path),
        )

    with smtplib.SMTP(host, port, timeout=30) as smtp:
        smtp.starttls()
        smtp.login(user, password)
        smtp.send_message(msg)

    return "ENVIADO"


