@app.route("/exportar_consumos")
@login_required
def exportar_consumos():
    # Exporta SOLO la data de un día. Por defecto, el día actual.
    fecha = request.args.get("fecha") or request.args.get("fecha_inicio") or hoy_iso()
    fecha = clean_text(fecha) or hoy_iso()
    rows = q_all("SELECT * FROM consumos WHERE fecha=? ORDER BY hora DESC,id DESC", (fecha,))
    datos = []
    for r in rows:
        d = dict(r)
        datos.append({
            "FECHA": d.get("fecha"), "HORA": d.get("hora"), "DNI": d.get("dni"),
            "TRABAJADOR": d.get("trabajador"), "AREA": d.get("area"), "TIPO_ALIMENTACION": d.get("tipo"),
            "PROVEEDOR": d.get("proveedor") or "", "CULTIVO": d.get("fundo") or "", "LOTE": d.get("observacion") or "",
            "RESPONSABLE": d.get("responsable") or "", "SUPERVISOR": d.get("supervisor") or "", "CANTIDAD": d.get("cantidad"),
            "PRECIO_UNITARIO": d.get("precio_unitario"), "TOTAL": d.get("total"), "ESTADO": d.get("estado")
        })
    df = pd.DataFrame(datos)
    output = BytesIO()
    df.to_excel(output, index=False)
    output.seek(0)
    return send_file(output, as_attachment=True, download_name=f"consumos_comedor_apb_{fecha}.xlsx",
                     mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")


@app.route("/descargar_cierre/<path:filename>")
@login_required
def descargar_cierre(filename):
    safe = os.path.basename(filename or "")
    if not safe:
        flash("No hay archivo de cierre para descargar.", "error")
        return redirect(url_for("reportes"))
    path = os.path.join(REPORT_DIR, safe)
    if not os.path.exists(path):
        # Regenera automáticamente desde la fecha incluida en el nombre cierre_comedor_YYYY_MM_DD.xlsx
        fecha = None
        m = re.search(r"(\d{4})_(\d{2})_(\d{2})", safe)
        if m:
            fecha = f"{m.group(1)}-{m.group(2)}-{m.group(3)}"
        if fecha:
            asegurar_archivo_cierre(fecha)
    if not os.path.exists(path):
        flash("El archivo no existe. Se intentó regenerar, pero no se encontró data para ese cierre.", "error")
        return redirect(url_for("reportes"))
    return send_file(path, as_attachment=True)


